CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, login_hash TEXT NOT NULL UNIQUE, recovery_hash TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS session_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS plans(user_id TEXT PRIMARY KEY,starts INTEGER NOT NULL,expires INTEGER NOT NULL,requests INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,activation_note TEXT NOT NULL DEFAULT 'pilot grant');
CREATE TABLE IF NOT EXISTS counters(key TEXT PRIMARY KEY,n INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS activation_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,activated_at INTEGER NOT NULL,note TEXT NOT NULL);
